    // Length
    cout << "Length: " << s3.length() << endl;  // 11

    // Search: find returns position, string::npos if not found
    int pos = s3.find("World");
    cout << "Found at: " << pos << endl;  // 6

    // Convert to uppercase
    for(char &c : s1) c = toupper(c);
    cout << s1 << endl;  // HELLO

    return 0;
}

