#include <algorithm>
using namespace std;

// Palindrome check - Two pointer
bool isPalindrome(string s) {
    int left = 0, right = s.length() - 1;
    while(left < right) {
        if(s[left] != s[right]) return false;
        left++;
        right--;
    }
    return true;
}

// Anagram check - Frequency count
bool isAnagram(string s1, string s2) {
    if(s1.length() != s2.length()) return false;
    int freq[26] = {0};
    for(int i = 0; i < s1.length(); i++) {
        freq[s1[i] - 'a']++;
        freq[s2[i] - 'a']--;
    }
    for(int i = 0; i < 26; i++) {
        if(freq[i] != 0) return false;
    }
    return true;
}

int main() {
    cout << isPalindrome("racecar") << endl;  // 1 (true)
    cout << isPalindrome("hello") << endl;     // 0 (false)
    cout << isAnagram("listen", "silent") << endl;  // 1 (true)
    cout << isAnagram("hello", "world") << endl;    // 0 (false)
    return 0;
}

